p-uselocalstorage-hook.starter:
import { useEffect, useState, type Dispatch, type SetStateAction } from 'react';

// Like useState, but persisted to localStorage as JSON. Survives corrupt JSON, a localStorage that
// throws, and server-side rendering (no window).
export function useLocalStorage<T>(key: string, initialValue: T): [T, Dispatch<SetStateAction<T>>] {
  throw new Error('Not implemented');
}

p-uselocalstorage-hook.solution:
import { useEffect, useState, type Dispatch, type SetStateAction } from 'react';

function read<T>(key: string, fallback: T): T {
  if (typeof window === 'undefined') return fallback;
  try {
    const raw = window.localStorage.getItem(key);
    return raw === null ? fallback : (JSON.parse(raw) as T);
  } catch {
    return fallback; // corrupt JSON or storage blocked
  }
}

export function useLocalStorage<T>(key: string, initialValue: T): [T, Dispatch<SetStateAction<T>>] {
  const [value, setValue] = useState<T>(() => read(key, initialValue));

  useEffect(() => {
    try {
      window.localStorage.setItem(key, JSON.stringify(value));
    } catch {
      // quota exceeded or storage blocked: keep working in memory
    }
  }, [key, value]);

  return [value, setValue];
}

// Usage
export function ThemePicker() {
  const [theme, setTheme] = useLocalStorage<'light' | 'dark'>('theme', 'light');
  return (
    <button type="button" onClick={() => setTheme((t) => (t === 'light' ? 'dark' : 'light'))}>
      Theme: {theme}
    </button>
  );
}

